"""Extract modern bounding-box centres reproducibly; no historical footprint claim."""
import argparse, hashlib, json, xml.etree.ElementTree as ET
from decimal import Decimal
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--source',required=True);p.add_argument('--out',required=True);a=p.parse_args()
raw=Path(a.source).read_bytes();root=ET.fromstring(raw);nodes={e.get('id'):e for e in root.findall('node')};records={}
for key,way_id in [('holy-sepulchre-context','1022672085'),('rock-sanctuary-context','4709536')]:
 w=next(e for e in root.findall('way') if e.get('id')==way_id);points=[nodes[n.get('ref')] for n in w.findall('nd')]
 centre={axis:float(((min(Decimal(n.get(axis)) for n in points)+max(Decimal(n.get(axis)) for n in points))/2).quantize(Decimal('.0000001'))) for axis in ['lat','lon']}
 records[key]={'osmWay':int(way_id),'version':int(w.get('version')),'timestamp':w.get('timestamp'),'point':centre}
data={'schema':'j3k.modern-core-location-reference.v1','source':{'url':'https://api.openstreetmap.org/api/0.6/map?bbox=35.222,31.770,35.242,31.785','rawSubsetSha256':hashlib.sha256(raw).hexdigest(),'attribution':'© OpenStreetMap contributors, ODbL'},'phases':['ottoman','outside-walls','modern'],'positionAuthority':'modern-map-building-bounds-centre-not-historical-survey','cores':records}
Path(a.out).write_text('// Generated by scripts/ingest_jerusalem_3000_core_reference.py; do not hand edit.\nexport const coreLocationReference = '+json.dumps(data,ensure_ascii=False,indent=2)+';\n')
